    h3: { fontSize: "1rem", fontWeight: 600 },
    button: { textTransform: "none", fontWeight: 600 },
    overline: { fontWeight: 600, letterSpacing: "0.06em" },
  },
  components: {
    MuiCard: {
      defaultProps: { variant: "outlined" },
