/**
 * The one MUI theme (ticket 05b): Inter, a neutral light background, one
 * primary colour, 8px spacing, rounded outlined cards and restrained shadows.
 */
import { createTheme } from "@mui/material/styles";

export const theme = createTheme({
  palette: {
    mode: "light",
    primary: { main: "#4f46e5" },
    background: { default: "#f6f7f9", paper: "#ffffff" },
    divider: "#e4e7ec",
    text: { primary: "#101828", secondary: "#475467" },
  },
  spacing: 8,
  shape: { borderRadius: 10 },
  typography: {
    fontFamily: '"Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif',
    h1: { fontSize: "1.75rem", fontWeight: 600 },
    h2: { fontSize: "1.25rem", fontWeight: 600 },
    h3: { fontSize: "1rem", fontWeight: 600 },
    button: { textTransform: "none", fontWeight: 600 },
    overline: { fontWeight: 600, letterSpacing: "0.06em" },
  },
  components: {
    MuiCard: {
      defaultProps: { variant: "outlined" },
      styleOverrides: {
        root: { boxShadow: "0 1px 2px rgba(16, 24, 40, 0.04)" },
      },
    },
    MuiAppBar: {
      defaultProps: { elevation: 0, color: "inherit" },
      styleOverrides: {
        root: { borderBottom: "1px solid #e4e7ec" },
      },
    },
    MuiButton: {
      defaultProps: { disableElevation: true },
    },
    MuiChip: {
      styleOverrides: {
        root: { fontWeight: 500 },
      },
    },
    MuiTableCell: {
      styleOverrides: {
        head: { fontWeight: 600, color: "#475467", whiteSpace: "nowrap" },
      },
    },
  },
});
/**
 * The one way a Run or Evaluation status, or a Verdict, is shown anywhere in
 * the UI (ticket 05b). Always colour plus text, never colour alone; statuses
 * still in progress carry a spinner and `aria-busy`.
 */
import Chip, { type ChipProps } from "@mui/material/Chip";
import CircularProgress from "@mui/material/CircularProgress";
import Box from "@mui/material/Box";
import type { EvaluationStatus, RunStatus, Verdict } from "@auto-apply/shared";

export type Status = RunStatus | EvaluationStatus;

interface Look {
  label: string;
  color: ChipProps["color"];
  variant: ChipProps["variant"];
  busy?: boolean;
}

const looks: Record<Status, Look> = {
  discovering: { label: "Discovering", color: "info", variant: "outlined", busy: true },
  evaluating: { label: "Evaluating", color: "info", variant: "outlined", busy: true },
  applying: { label: "Applying", color: "info", variant: "outlined", busy: true },
  completed: { label: "Completed", color: "success", variant: "filled" },
  queued: { label: "Queued", color: "default", variant: "filled" },
  held: { label: "Needs you", color: "warning", variant: "filled" },
  skipped: { label: "Skipped", color: "default", variant: "outlined" },
  blocked: { label: "Blocked", color: "error", variant: "outlined" },
  submitted: { label: "Submitted", color: "success", variant: "filled" },
  failed: { label: "Failed", color: "error", variant: "filled" },
};

export function StatusChip({ status }: { status: Status }) {
  const look = looks[status];
  return (
    <Chip
      data-testid="status-chip"
      data-status={status}
      aria-busy={look.busy ? true : undefined}
      size="small"
      color={look.color}
      variant={look.variant}
      icon={
        look.busy ? <CircularProgress size={12} color="inherit" aria-hidden="true" /> : undefined
      }
      label={
        status === "submitted" ? (
          <>
            {look.label}{" "}
            <Box
              component="span"
              sx={{
                ml: 0.5,
                px: 0.75,
                py: 0.125,
                borderRadius: 1,
                fontSize: "0.6875rem",
                bgcolor: "rgba(255, 255, 255, 0.25)",
              }}
            >
              simulated
            </Box>
          </>
        ) : (
          look.label
        )
      }
    />
  );
}

const verdictLooks: Record<
  Verdict,
  { label: string; color: ChipProps["color"]; variant: ChipProps["variant"] }
> = {
  APPLY_NOW: { label: "APPLY NOW", color: "primary", variant: "filled" },
  APPLY: { label: "APPLY", color: "primary", variant: "outlined" },
  STRETCH: { label: "STRETCH", color: "default", variant: "outlined" },
  BLOCKED: { label: "BLOCKED", color: "error", variant: "outlined" },
};

export function VerdictChip({ verdict }: { verdict: Verdict | null }) {
  if (!verdict) {
    return (
      <Box component="span" sx={{ color: "text.secondary" }}>
        —
      </Box>
    );
  }
  const look = verdictLooks[verdict];
  return <Chip size="small" label={look.label} color={look.color} variant={look.variant} />;
}
/**
 * The live stream's connection state (CODING_STANDARDS, Web): a coloured dot
 * plus a word, never the dot alone.
 */
import Box from "@mui/material/Box";
import Stack from "@mui/material/Stack";
import Typography from "@mui/material/Typography";
import type { Connection } from "../run/useRunStream";

const looks: Record<Connection, { label: string; color: string; pulse: boolean }> = {
  connecting: { label: "Connecting…", color: "info.main", pulse: true },
  live: { label: "Live", color: "success.main", pulse: true },
  reconnecting: { label: "Reconnecting…", color: "warning.main", pulse: true },
  closed: { label: "Closed", color: "text.disabled", pulse: false },
};

export function ConnectionIndicator({ connection }: { connection: Connection }) {
  const look = looks[connection];
  return (
    <Stack
      direction="row"
      spacing={0.75}
      sx={{ alignItems: "center" }}
      data-testid="connection"
      title="Live updates from the server"
    >
      <Box
        aria-hidden="true"
        sx={{
          width: 8,
          height: 8,
          borderRadius: "50%",
          bgcolor: look.color,
          ...(look.pulse && {
            "@keyframes pulse": { "50%": { opacity: 0.35 } },
            animation: "pulse 1.6s ease-in-out infinite",
            "@media (prefers-reduced-motion: reduce)": { animation: "none" },
          }),
        }}
      />
      <Typography variant="body2" color="text.secondary">
        {look.label}
      </Typography>
    </Stack>
  );
}
/**
 * The frame around every view (ticket 05b): an app bar with the product name,
 * a Prototype badge and the nav tabs; a max-width content container; and a
 * quiet footer that says submissions are simulated (D18).
 */
import type { ReactNode } from "react";
import { Link, useLocation } from "react-router-dom";
import AppBar from "@mui/material/AppBar";
import Box from "@mui/material/Box";
import Chip from "@mui/material/Chip";
import Container from "@mui/material/Container";
import Stack from "@mui/material/Stack";
import Tab from "@mui/material/Tab";
import Tabs from "@mui/material/Tabs";
import Toolbar from "@mui/material/Toolbar";
import Typography from "@mui/material/Typography";
import AutoAwesomeIcon from "@mui/icons-material/AutoAwesome";
import { ApiHealth } from "./ApiHealth";

export const navItems = [
  { path: "/", label: "Run" },
  { path: "/applied", label: "Applied jobs" },
  { path: "/scanned", label: "Scanned jobs" },
  { path: "/settings", label: "Settings" },
] as const;

export function AppShell({ children }: { children: ReactNode }) {
  const { pathname } = useLocation();
  const current = navItems.find((item) => item.path === pathname)?.path ?? false;

  return (
    <Box sx={{ minHeight: "100vh", display: "flex", flexDirection: "column" }}>
      <AppBar position="sticky">
        <Container maxWidth="lg">
          <Toolbar disableGutters sx={{ gap: 2, minHeight: { xs: 56 } }}>
            <Stack direction="row" spacing={1} sx={{ alignItems: "center", flexShrink: 0 }}>
              <AutoAwesomeIcon color="primary" fontSize="small" aria-hidden="true" />
              <Typography component="span" sx={{ fontWeight: 700 }}>
                AI Auto-apply
              </Typography>
              <Chip label="Prototype" size="small" variant="outlined" />
            </Stack>
          </Toolbar>
          <Tabs
            value={current}
            aria-label="Views"
            variant="scrollable"
            scrollButtons={false}
            sx={{ minHeight: 40, mt: -1 }}
          >
            {navItems.map((item) => (
              <Tab
                key={item.path}
                label={item.label}
                value={item.path}
                component={Link}
                to={item.path}
                sx={{ minHeight: 40, px: 1.5 }}
              />
            ))}
          </Tabs>
        </Container>
      </AppBar>

      <Container component="main" maxWidth="lg" sx={{ flex: 1, py: 4 }}>
        {children}
      </Container>

      <Box component="footer" sx={{ borderTop: 1, borderColor: "divider", py: 2 }}>
        <Container maxWidth="lg">
          <Stack
            direction={{ xs: "column", sm: "row" }}
            spacing={1}
            sx={{ justifyContent: "space-between" }}
          >
            <Typography variant="caption" color="text.secondary">
              Submissions are simulated · payloads are built and stored, never sent
            </Typography>
            <ApiHealth />
          </Stack>
        </Container>
      </Box>
    </Box>
  );
}
/**
 * A quiet line in the footer saying which API, namespace and store the page is
 * talking to, so an in-memory store is never mistaken for persistence (ADR-0004).
 */
import { useEffect, useState } from "react";
import Typography from "@mui/material/Typography";
import { healthResponseSchema, type HealthResponse } from "@auto-apply/shared";
import { API_URL } from "../api";

type State =
  | { kind: "loading" }
  | { kind: "error"; message: string }
  | { kind: "ready"; health: HealthResponse };

export function ApiHealth() {
  const [state, setState] = useState<State>({ kind: "loading" });

  useEffect(() => {
    let cancelled = false;

    fetch(`${API_URL}/api/health`)
      .then(async (res) => {
        if (!res.ok) {
          throw new Error(`API responded ${res.status}`);
        }
        return healthResponseSchema.parse(await res.json());
      })
      .then((health) => {
        if (!cancelled) {
          setState({ kind: "ready", health });
        }
      })
      .catch((err: unknown) => {
        if (!cancelled) {
          setState({
            kind: "error",
            message: err instanceof Error ? err.message : "Unknown error",
          });
        }
      });

    return () => {
      cancelled = true;
    };
  }, []);

  if (state.kind === "loading") {
    return (
      <Typography variant="caption" color="text.secondary">
        Checking API…
      </Typography>
    );
  }
  if (state.kind === "error") {
    return (
      <Typography variant="caption" color="error" role="alert">
        Could not reach the API: {state.message}
      </Typography>
    );
  }
  const { health } = state;
  return (
    <Typography variant="caption" color="text.secondary">
      API {health.status} · namespace {health.namespace} ·{" "}
      {health.repo === "memory" ? "In-memory (not persisted)" : "Firestore"}
    </Typography>
  );
}
/**
 * A view whose ticket has not landed yet (Applied jobs: 11, Scanned jobs and
 * Settings: 12). It says so plainly instead of showing an empty list that looks
 * like real data.
 */
import Card from "@mui/material/Card";
import CardContent from "@mui/material/CardContent";
import Stack from "@mui/material/Stack";
import Typography from "@mui/material/Typography";

export function PlaceholderPage({ title, description }: { title: string; description: string }) {
  return (
    <Stack spacing={3}>
      <Typography variant="h1">{title}</Typography>
      <Card>
        <CardContent sx={{ py: 6, textAlign: "center" }}>
          <Typography variant="h3" gutterBottom>
            Not built yet
          </Typography>
          <Typography color="text.secondary">{description}</Typography>
        </CardContent>
      </Card>
    </Stack>
  );
}
/**
 * The Evaluations of a Run as a table, one row per Job Key, updated in place
 * as `eval` events arrive.
 */
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell from "@mui/material/TableCell";
import TableContainer from "@mui/material/TableContainer";
import TableHead from "@mui/material/TableHead";
import TableRow from "@mui/material/TableRow";
import Typography from "@mui/material/Typography";
import type { Ats, Evaluation } from "@auto-apply/shared";
import { StatusChip, VerdictChip } from "../ui/StatusChip";

const atsLabels: Record<Ats, string> = {
  greenhouse: "Greenhouse",
  lever: "Lever",
  ashby: "Ashby",
};

export function JobsTable({ evaluations }: { evaluations: Evaluation[] }) {
  return (
    <TableContainer>
      <Table size="small" aria-label="Jobs in this run">
        <TableHead>
          <TableRow>
            <TableCell>Company</TableCell>
            <TableCell>Role</TableCell>
            <TableCell>Source</TableCell>
            <TableCell>Verdict</TableCell>
            <TableCell align="right">Score</TableCell>
            <TableCell>Status</TableCell>
            <TableCell>Reason</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {evaluations.map(({ jobKey, posting, verdict, score, status, reason }) => (
            <TableRow key={jobKey} hover>
              <TableCell sx={{ whiteSpace: "nowrap" }}>{posting.company}</TableCell>
              <TableCell sx={{ fontWeight: 500 }}>{posting.title}</TableCell>
              <TableCell sx={{ whiteSpace: "nowrap" }}>
                {atsLabels[posting.ats]}
                <Typography component="span" variant="body2" color="text.secondary">
                  {" "}
                  · {posting.board}
                </Typography>
              </TableCell>
              <TableCell>
                <VerdictChip verdict={verdict} />
              </TableCell>
              <TableCell align="right" sx={{ fontVariantNumeric: "tabular-nums" }}>
                {score === null ? "—" : Math.round(score)}
              </TableCell>
              <TableCell>
                <StatusChip status={status} />
              </TableCell>
              <TableCell sx={{ color: "text.secondary", minWidth: 200 }}>{reason ?? "—"}</TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
}

